def make_dict_from_elems_in_index(keys, values, index):
    # Pick the element at `index` from each list and pair them up.
    return {keys[index]: values[index]}

def count_unique_even_odd(numbers):
    unique = set(numbers)
    even = sum(1 for x in unique if x % 2 == 0)
    odd = sum(1 for x in unique if x % 2 != 0)
    return {"even": even, "odd": odd}

