def filter_students(data, criteria):
    result = set()
    for name, scores in data.items():
        avg = sum(scores) / len(scores)
        if criteria == 'excellent' and avg >= 85:
            result.add(name)
        elif criteria == 'good' and 50 <= avg < 85:
            result.add(name)
        elif criteria == 'all_pass' and all(s >= 50 for s in scores):
            result.add(name)
        elif criteria == 'balanced' and (max(scores) - min(scores)) <= 10:
            result.add(name)
    return result

def is_decreasing_number(n: int) -> bool:
    s = str(n)
    # Each digit must be strictly less than the one before it.
    return all(int(s[i]) < int(s[i - 1]) for i in range(1, len(s)))
